{
  "execucao_id": "etapa9-v05-90-BHT-R2-20261027-k_0ca7-B-2",
  "projeto_id": "q_d92a",
  "versao": "v1.0-ampliacao-desenvolvimento",
  "evento_id": "e_7655ef",
  "view_hash": "7c33bd48669b085655dcfdfdf8c16fcee8ddfd3cd77bf632c064797d50de3a9d",
  "fim_base": {
    "estado": "exato",
    "valor": 12,
    "direcao": "desconhecida",
    "evidencias": [{"fonte_id": "f_36c2", "localizador": "L02"}],
    "lacunas": [],
    "motivo": "Término de referência da linha base declarado como D12.",
    "unidade": "dia_corrido"
  },
  "fim_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_113c08", "localizador": "L01"},
      {"fonte_id": "f_36c2", "localizador": "L02"}
    ],
    "lacunas": ["A ficha d_a70f, indicada como contendo todas as precedências, não está disponível; sem as relações não é possível calcular o término após a alteração das durações."],
    "motivo": "O aviso altera durações, mas a view não fornece as precedências necessárias para determinar o efeito no marco final.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_113c08", "localizador": "L01"},
      {"fonte_id": "f_36c2", "localizador": "L02"}
    ],
    "lacunas": ["O término novo não pode ser calculado sem as precedências da ficha d_a70f."],
    "motivo": "A linha base é conhecida, mas não há suporte suficiente para determinar o término novo e, portanto, sua variação.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_36c2", "localizador": "L02"},
      {"fonte_id": "f_b915", "localizador": "L01"}
    ],
    "lacunas": [],
    "motivo": "Custo de referência declarado como R$ 1.650,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_113c08", "localizador": "L01"},
      {"fonte_id": "f_493d", "localizador": "L01"},
      {"fonte_id": "f_b915", "localizador": "L01"}
    ],
    "lacunas": ["O término novo não pode ser determinado sem as precedências; o custo do apoio depende do término final."],
    "motivo": "O aviso não tem cobrança direta, mas o custo total inclui apoio cujo valor depende da data final; a alteração de custo não pode ser calculada sem determinar essa data.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_113c08", "localizador": "L01"},
      {"fonte_id": "f_493d", "localizador": "L01"},
      {"fonte_id": "f_36c2", "localizador": "L02"}
    ],
    "lacunas": ["Sem precedências não se determina o término novo, necessário para apurar o custo do apoio e sua variação."],
    "motivo": "O custo base é conhecido, mas o custo novo depende do término final, que não é calculável com os dados disponíveis.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A linha base declara término D12 e custo de 165000 centavos. O aviso altera duas durações e não tem cobrança direta, mas a view não inclui as precedências referidas pela fonte; por isso não é possível estimar o término novo nem o custo condicionado ao término."
}

